<!-- Generated by Copilot; rows rebuilt as Vuetify fields (labelled inputs) for a11y -->
<template>
  <v-card
    class="orbital-editor"
    variant="outlined"
  >
    <v-card-title class="text-subtitle-1 py-2">Orbital Elements Editor</v-card-title>
    <v-card-text class="pa-2">
      <div
        v-if="currentPosition"
        class="position-display mb-3 pa-2"
      >
        <div class="position-title">Position at epoch (JD {{ localElements.jdEquinox?.toFixed(2) }}), WWT x, y, z:</div>
        <div class="position-coords">
          {{ fmtPosition(currentPosition.x) }}<br />
          {{ fmtPosition(currentPosition.y) }}<br />
          {{ fmtPosition(currentPosition.z) }}
        </div>
      </div>

      <div
        v-for="field in fields"
        :key="field.key"
        class="element-row"
      >
        <v-text-field
          v-model.number="localElements[field.key]"
          :label="field.label"
          type="number"
          :step="0.0001"
          density="compact"
          variant="outlined"
          hide-details
          @update:model-value="updateOrbit"
        />
        <v-slider
          v-model="localElements[field.key]"
          :aria-label="`${field.label} slider`"
          :min="field.min"
          :max="field.max"
          :step="0.0001"
          density="compact"
          hide-details
          @update:model-value="updateOrbit"
        />
        <span class="delta-display">{{ getDelta(field.key) }}</span>
        <v-btn
          icon="mdi-refresh"
          size="x-small"
          variant="text"
          :aria-label="`reset ${field.label}`"
          @click="resetElement(field.key)"
        />
      </div>
    </v-card-text>
  </v-card>
</template>

<script setup lang="ts">
import { ref, watch, computed } from "vue";
import { LayerManager, ELL } from "@wwtelescope/engine";
import type { OrbitLayer, EOE } from "@wwtelescope/engine";
import { AltUnits } from "@wwtelescope/engine-types";
import { AU_M } from "../constants";

type ElementKey = "a" | "e" | "i" | "omega" | "w" | "meanAnnomolyOut" | "n" | "jdEquinox";
type EditableElements = Pick<EOE, ElementKey | "t">;

const props = defineProps<{
  orbitLayer: OrbitLayer | null;
}>();

const fields: { key: ElementKey; label: string; min: number; max: number }[] = [
  { key: "a", label: "a (AU)", min: 0.1, max: 50 },
  { key: "e", label: "e", min: 0, max: 0.99 },
  { key: "i", label: "i (°)", min: -90, max: 90 },
  { key: "omega", label: "Ω (°)", min: 0, max: 360 },
  { key: "w", label: "ω (°)", min: 0, max: 360 },
  { key: "meanAnnomolyOut", label: "M (°)", min: -360, max: 360 },
  { key: "n", label: "n (°/d)", min: 0, max: 1 },
  { key: "jdEquinox", label: "JD", min: 2400000, max: 2500000 },
];

// Default/initial orbital elements (store original values)
const defaultElements = ref<EditableElements>({
  a: 3.1,
  e: 0.25,
  i: 2.7,
  w: 197,
  omega: 121,
  meanAnnomolyOut: 120,
  n: 0.18,
  t: 2460334.79,
  jdEquinox: 2461000.5,
});

// Local copy of orbital elements for editing
const localElements = ref<EditableElements>({ ...defaultElements.value });

// ELL works in the units of `a` (AU here). It writes meanAnnomolyOut, hence the copy; and t is the
// perihelion time ReferenceFrame.get_elements derives (epoch - M0/n), not the epoch the old code passed
const currentPosition = computed(() => {
  const el = localElements.value;
  if (!el.jdEquinox) return null;
  try {
    return ELL.calculateRectangularJD(el.jdEquinox, {
      ...el,
      t: el.jdEquinox - (el.meanAnnomolyOut ?? 0) / el.n,
    } as EOE);
  } catch (e) {
    console.error("Error calculating position:", e);
    return null;
  }
});

const fmtPosition = (v: number) => `${v.toFixed(6)} AU`;

// Initialize local elements from the layer
watch(
  () => props.orbitLayer,
  (layer) => {
    const frame = layer?.get_frames()[0];
    if (!frame) return;
    const elements: EditableElements = {
      a: frame.semiMajorAxis / AU_M,
      e: frame.eccentricity,
      i: frame.inclination,
      w: frame.argumentOfPeriapsis,
      omega: frame.longitudeOfAscendingNode,
      meanAnnomolyOut: frame.meanAnomolyAtEpoch,
      n: frame.meanDailyMotion,
      t: frame.epoch,
      jdEquinox: frame.epoch,
    };
    defaultElements.value = { ...elements };
    localElements.value = { ...elements };
  },
  { immediate: true },
);

/**
 * Updates the orbit layer's frame in place with the edited elements
 */
function updateOrbit() {
  const frame = props.orbitLayer?.get_frames()[0];
  if (!frame) return;
  const el = localElements.value;

  frame.semiMajorAxis = el.a * AU_M;
  frame.semiMajorAxisUnits = AltUnits.meters;
  frame.eccentricity = el.e;
  frame.inclination = el.i;
  frame.argumentOfPeriapsis = el.w;
  frame.longitudeOfAscendingNode = el.omega;
  frame.meanAnomolyAtEpoch = el.meanAnnomolyOut ?? 0;
  frame.meanDailyMotion = el.n;
  frame.epoch = el.jdEquinox;

  // OrbitLayer.draw rebuilds the Orbit (from get_elements()) when it is null
  frame.set_orbit(null);

  LayerManager.set_version(LayerManager.get_version() + 1);
  LayerManager.loadTree();
}

function resetElement(key: ElementKey) {
  const defaultValue = defaultElements.value[key];
  if (defaultValue !== undefined) {
    localElements.value[key] = defaultValue;
    updateOrbit();
  }
}

function getDelta(key: ElementKey): string {
  const current = localElements.value[key];
  const original = defaultElements.value[key];
  if (current === undefined || original === undefined) return "";
  const delta = current - original;
  if (Math.abs(delta) < 0.0001) return "";
  return `${delta > 0 ? "+" : ""}${delta.toFixed(5)}`;
}
</script>

